import { ProjectRepository } from "../domain/project-repository";
import { TaskRepository } from "../domain/task-repository";
import { Task } from "../domain/task";
import { IdGenerator } from "../domain/id-generator";
import { UserRepository } from "../domain/user-repository";
import { ApplicationError } from "./application-error";
import { CreateTaskInput, TaskOutput } from "./dtos";

export class CreateTaskUseCase {
  public constructor(
    private readonly tasks: TaskRepository,
    private readonly projects: ProjectRepository,
    private readonly users: UserRepository,
    private readonly ids: IdGenerator,
  ) {}

  public async execute(input: CreateTaskInput): Promise<TaskOutput> {
    if (!input.title?.trim() || !input.description?.trim()) throw new ApplicationError("title and description are required", 400);
    if (!(await this.projects.findById(input.projectId))) throw new ApplicationError("project not found", 404);
    if (input.assigneeId && !(await this.users.findById(input.assigneeId))) throw new ApplicationError("assignee not found", 400);
    const dueDate = input.dueDate ? new Date(input.dueDate) : undefined;
    if (dueDate && Number.isNaN(dueDate.getTime())) throw new ApplicationError("dueDate must be a valid date", 400);
    const task = new Task(this.ids.next(), input.projectId, input.title.trim(), input.description.trim(), dueDate, input.assigneeId, input.status ?? "todo");
    await this.tasks.save(task);
    return this.toOutput(task);
  }

  private toOutput(task: Task): TaskOutput {
    return { id: task.id, projectId: task.projectId, title: task.title, description: task.description, dueDate: task.dueDate?.toISOString(), assigneeId: task.assigneeId, status: task.getStatus() };
  }
}

